cat > /tmp/probe.mjs <<'EOF'
import { execFileSync } from 'child_process';
const EXE = '/workspace/dataset/test19_executable';
// usage: node probe.mjs <block: d|e|f|final|all> <json with the probed arg named by block>
const which = process.argv[2];
const probeVal = JSON.parse(process.argv[3]);
const S = { a:'@@1@@', b:'@@2@@', c:'@@3@@', d:'@@4@@', e:'@@5@@', f:'@@6@@' };
const args = {...S};
if (which === 'd') args.d = probeVal;
else if (which === 'e') args.e = probeVal;
else if (which === 'f') args.f = probeVal;
else if (which === 'final') { /* probeVal = {a,b,c,d,e,f} */ Object.assign(args, probeVal); }
const out = execFileSync(EXE, ['--a',args.a,'--b',args.b,'--c',args.c,'--d',args.d,'--e',args.e,'--f',args.f], {encoding:'utf8', maxBuffer: 1<<28});
const P = i => `<p>@@${i}@@</p>\n`;
function block(name, s) { process.stdout.write(`=== ${name} ===\n${JSON.stringify(s)}\n--- raw ---\n${s}\n`); }
if (which === 'd') {
  const start = P(1)+P(2)+P(3);
  const end = '\n'+P(5);
  const i0 = out.indexOf(start)+start.length;
  const i1 = out.indexOf(end, i0);
  block('d', out.slice(i0, i1));
} else if (which === 'e') {
  const start = P(1)+P(2)+P(3)+P(4);
  const end = '\n'+P(6);
  const i0 = out.indexOf(start)+start.length;
  const i1 = out.indexOf(end, i0);
  block('e', out.slice(i0, i1));
} else if (which === 'f') {
  const start = P(1)+P(2)+P(3)+P(4)+P(5);
  const end = '\n<h1>Combined Document</h1>';
  const i0 = out.indexOf(start)+start.length;
  const i1 = out.indexOf(end, i0);
  block('f', out.slice(i0, i1));
} else if (which === 'final') {
  const idx = out.lastIndexOf('</article>\n');
  block('final', out.slice(idx+'</article>\n'.length, -1));
}
EOF
